from collections import deque
def maxSlidingWindow(nums, k):
    q = deque()                     # 存下标，对应值递减
    res = []
    for i, x in enumerate(nums):
        while q and nums[q[-1]] <= x:
            q.pop()                 # 淘汰永远当不了最大值的
        q.append(i)
        if q[0] <= i - k:           # 队首滑出窗口
            q.popleft()
        if i >= k - 1:
            res.append(nums[q[0]])  # 队首即窗口最大
    return res
